      "label": "A",
      "phrases": [
        {
          "id": "V3-01",
          "zh": "今天我们聊些什么呢？"
        },
        {
          "id": "V3-02",
          "zh": "和你一起唱什么歌呢？"
        },
        {
          "id": "V3-03",
          "zh": "连无人知晓的花儿也"
        }
      ]
    },
    {
      "label": "B",
